"""
Pydantic schemas for request/response validation.
"""

from __future__ import annotations

from typing import List, Optional
from pydantic import BaseModel, Field, field_validator


MEDICAL_DISCLAIMER = (
    "This tool is an educational prototype and does not provide medical advice, "
    "diagnosis, or treatment. The results are generated by a machine learning model "
    "trained on a synthetic dataset and have not been clinically validated. "
    "Always consult a qualified healthcare professional for any health concerns. "
    "Do not disregard professional medical advice based on anything shown here."
)


class PredictRequest(BaseModel):
    symptoms: List[str] = Field(
        ...,
        min_length=1,
        description="List of symptom names to assess.",
        examples=[["itching", "skin_rash", "nodal_skin_eruptions"]],
    )

    @field_validator("symptoms")
    @classmethod
    def symptoms_not_all_empty(cls, v: List[str]) -> List[str]:
        if not v:
            raise ValueError("symptoms list must not be empty.")
        if all(not s.strip() for s in v):
            raise ValueError("All symptom strings are empty.")
        return v


class CandidateCondition(BaseModel):
    rank: int = Field(..., description="1-indexed rank (1 = most likely).")
    condition: str = Field(..., description="Disease / condition name.")
    score: float = Field(..., description="Model vote fraction (not a calibrated probability).")
    score_label: str = Field(default="model_vote_fraction", description="Label describing score semantics.")
    description: Optional[str] = Field(None, description="General description of the condition.")
    precautions: List[str] = Field(default_factory=list, description="General precautionary steps.")
    matching_symptoms: List[str] = Field(default_factory=list, description="Input symptoms associated with this condition in training data.")


class PredictResponse(BaseModel):
    candidates: List[CandidateCondition] = Field(
        ..., description="Ranked candidate conditions (up to 5)."
    )
    known_symptoms: List[str] = Field(..., description="Input symptoms recognized by the model.")
    unknown_symptoms: List[str] = Field(
        default_factory=list,
        description="Input symptoms not found in the training vocabulary.",
    )
    model_version: str = Field(..., description="Identifier of the model used.")
    disclaimer: str = Field(default=MEDICAL_DISCLAIMER)
    uncertainty_note: str = Field(
        default=(
            "Scores reflect how the Random Forest model distributes votes among "
            "its decision trees for the given symptom set. They are not calibrated "
            "disease probabilities and must not be used as a basis for clinical decisions."
        )
    )


class HealthResponse(BaseModel):
    status: str
    model_loaded: bool
    model_version: Optional[str]
    vocabulary_size: int


class ErrorResponse(BaseModel):
    error: str
    detail: Optional[str] = None
